import React, { useState } from "react";

export default function TouristRegistration() {
  const [formData, setFormData] = useState({
    name: "",
    country: "",
    phone: "",
    idProof: "",
  });
  const [registered, setRegistered] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!formData.name || !formData.country || !formData.phone || !formData.idProof) {
      alert("Please fill all fields!");
      return;
    }
    setRegistered(true);
  };

  return (
    <div
      style={{
        height: "100vh",
        backgroundImage:
          "url('https://images.unsplash.com/photo-1603262110263-fb7b3c88792a?auto=format&fit=crop&w=1500&q=80')",
        backgroundSize: "cover",
        backgroundPosition: "center",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Poppins, sans-serif",
        backdropFilter: "blur(8px)",
        color: "#333",
      }}
    >
      {!registered ? (
        <form
          onSubmit={handleSubmit}
          style={{
            background: "rgba(255, 255, 255, 0.2)",
            backdropFilter: "blur(12px)",
            borderRadius: "20px",
            padding: "40px",
            width: "350px",
            textAlign: "center",
            boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
            animation: "fadeIn 1s ease-in-out",
            color: "white",
          }}
        >
          <h2
            style={{
              color: "#fff",
              marginBottom: "10px",
              fontWeight: "600",
              fontSize: "26px",
            }}
          >
            🧳 Tourist Registration
          </h2>
          <p style={{ fontSize: "14px", color: "#f1f1f1", marginBottom: "25px" }}>
            Start your smart and safe journey with us 🌍
          </p>

          <input
            type="text"
            name="name"
            placeholder="Full Name"
            value={formData.name}
            onChange={handleChange}
            style={inputStyle}
          />
          <input
            type="text"
            name="country"
            placeholder="Country of Origin"
            value={formData.country}
            onChange={handleChange}
            style={inputStyle}
          />
          <input
            type="tel"
            name="phone"
            placeholder="Phone Number"
            value={formData.phone}
            onChange={handleChange}
            style={inputStyle}
          />
          <input
            type="text"
            name="idProof"
            placeholder="Aadhaar / Passport / ID Proof"
            value={formData.idProof}
            onChange={handleChange}
            style={inputStyle}
          />

          <button
            type="submit"
            style={buttonStyle}
            onMouseOver={(e) => (e.target.style.background = "#ff6f00")}
            onMouseOut={(e) => (e.target.style.background = "#ff9800")}
          >
            Register
          </button>
        </form>
      ) : (
        <div
          style={{
            background: "rgba(255, 255, 255, 0.2)",
            backdropFilter: "blur(12px)",
            borderRadius: "20px",
            padding: "40px",
            width: "350px",
            textAlign: "center",
            color: "white",
            animation: "fadeIn 1s ease-in-out",
          }}
        >
          <h2 style={{ color: "#fff" }}>Welcome, {formData.name}! 🎉</h2>
          <p style={{ marginTop: "10px", fontSize: "15px" }}>
            Your registration is successful.<br />
            Your <strong>Block ID</strong> will be generated shortly.
          </p>
        </div>
      )}
    </div>
  );
}

const inputStyle = {
  width: "100%",
  padding: "12px",
  marginBottom: "12px",
  borderRadius: "10px",
  border: "none",
  outline: "none",
  background: "rgba(255,255,255,0.8)",
  color: "#333",
  fontSize: "14px",
};

const buttonStyle = {
  width: "100%",
  padding: "12px",
  backgroundColor: "#ff9800",
  color: "white",
  border: "none",
  borderRadius: "10px",
  cursor: "pointer",
  fontWeight: "bold",
  fontSize: "16px",
  transition: "0.3s ease",
};
